BEGIN;
CREATE SCHEMA erp_cheque_private;
REVOKE ALL ON SCHEMA erp_cheque_private FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE public.erp_cheque_books(cafe_id uuid NOT NULL REFERENCES public.cafes(id),id uuid PRIMARY KEY,revision integer NOT NULL DEFAULT 1,bank_id uuid NOT NULL,number text NOT NULL CHECK(length(btrim(number)) BETWEEN 1 AND 100),first_serial bigint NOT NULL CHECK(first_serial BETWEEN 1 AND 999999999999),last_serial bigint NOT NULL CHECK(last_serial>=first_serial AND last_serial<=999999999999),currency text NOT NULL CHECK(currency~'^[A-Z]{3}$'),active boolean NOT NULL,note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(cafe_id,id),UNIQUE(cafe_id,bank_id,number),FOREIGN KEY(cafe_id,bank_id) REFERENCES public.bf_accounts(cafe_id,id));
CREATE TABLE public.erp_cheques(cafe_id uuid NOT NULL REFERENCES public.cafes(id),id uuid PRIMARY KEY,revision integer NOT NULL DEFAULT 1,kind text NOT NULL CHECK(kind IN('payable','receivable')),status text NOT NULL CHECK(status IN('issued','received','delivered','deposited','collected','rejected','cancelled')),number text NOT NULL CHECK(length(btrim(number)) BETWEEN 1 AND 100),book_id uuid,bank_id uuid NOT NULL,counter_account_id uuid NOT NULL,party_id uuid,amount numeric(18,2) NOT NULL CHECK(amount>0),base_amount numeric(18,2) NOT NULL CHECK(base_amount>0),currency text NOT NULL,exchange_rate numeric(18,8) NOT NULL CHECK(exchange_rate>0),issued_on date NOT NULL,due_on date,name text NOT NULL,payload jsonb NOT NULL,holding_account_id uuid,deposit_account_id uuid,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES auth.users(id),UNIQUE(cafe_id,id),FOREIGN KEY(cafe_id,book_id) REFERENCES public.erp_cheque_books(cafe_id,id),FOREIGN KEY(cafe_id,bank_id) REFERENCES public.bf_accounts(cafe_id,id),FOREIGN KEY(cafe_id,counter_account_id) REFERENCES public.bf_accounts(cafe_id,id),FOREIGN KEY(cafe_id,party_id) REFERENCES public.bf_parties(cafe_id,id),FOREIGN KEY(cafe_id,holding_account_id) REFERENCES public.bf_accounts(cafe_id,id),FOREIGN KEY(cafe_id,deposit_account_id) REFERENCES public.bf_accounts(cafe_id,id),CHECK(due_on IS NULL OR due_on>=issued_on));
CREATE UNIQUE INDEX erp_cheques_payable_number ON public.erp_cheques(cafe_id,bank_id,number) WHERE kind='payable';
CREATE UNIQUE INDEX erp_cheques_receivable_number ON public.erp_cheques(cafe_id,lower(payload->>'issuerBank'),number,coalesce(party_id,'00000000-0000-0000-0000-000000000000')) WHERE kind='receivable';
CREATE INDEX erp_cheques_list ON public.erp_cheques(cafe_id,kind,status,due_on,issued_on);
CREATE TABLE public.erp_cheque_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cafe_id uuid NOT NULL,cheque_id uuid NOT NULL,action text NOT NULL,from_status text,to_status text NOT NULL,effective_on date NOT NULL,document_id uuid,reversal_of uuid,payload jsonb NOT NULL,actor uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(cafe_id,id),UNIQUE(cafe_id,document_id),UNIQUE(cafe_id,reversal_of),FOREIGN KEY(cafe_id,cheque_id) REFERENCES public.erp_cheques(cafe_id,id),FOREIGN KEY(cafe_id,document_id) REFERENCES public.bf_documents(cafe_id,id),FOREIGN KEY(cafe_id,reversal_of) REFERENCES public.erp_cheque_events(cafe_id,id));
CREATE INDEX erp_cheque_events_history ON public.erp_cheque_events(cafe_id,cheque_id,created_at);
CREATE TABLE public.erp_cheque_settings(cafe_id uuid PRIMARY KEY REFERENCES public.cafes(id),revision integer NOT NULL DEFAULT 1,payload jsonb NOT NULL);
CREATE TABLE erp_cheque_private.requests(cafe_id uuid NOT NULL,request_id uuid NOT NULL,actor uuid NOT NULL,action text NOT NULL,payload jsonb NOT NULL,result jsonb NOT NULL,PRIMARY KEY(cafe_id,request_id));
ALTER TABLE erp_cheque_private.requests ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.erp_cheque_audit(cafe_id uuid NOT NULL REFERENCES public.cafes(id),id uuid PRIMARY KEY DEFAULT gen_random_uuid(),record_id uuid,action text NOT NULL,actor uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE public.erp_cheque_audit ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.erp_cheque_audit FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION erp_cheque_private.audit_guard() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN RAISE EXCEPTION 'سجل التدقيق غير قابل للتعديل أو الحذف' USING ERRCODE='42501';END $$;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON erp_cheque_private.requests FOR EACH ROW EXECUTE FUNCTION erp_cheque_private.audit_guard();
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON public.erp_cheque_audit FOR EACH ROW EXECUTE FUNCTION erp_cheque_private.audit_guard();
CREATE FUNCTION erp_cheque_private.event_guard() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN IF TG_OP='UPDATE' OR OLD.document_id IS NOT NULL THEN RAISE EXCEPTION 'الحركة المالية المسجلة غير قابلة للتعديل أو الحذف' USING ERRCODE='42501';END IF;RETURN OLD;END $$;
CREATE TRIGGER immutable_posted_event BEFORE UPDATE OR DELETE ON public.erp_cheque_events FOR EACH ROW EXECUTE FUNCTION erp_cheque_private.event_guard();
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['erp_cheque_books','erp_cheques','erp_cheque_events','erp_cheque_settings'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC,anon,authenticated,service_role',t);END LOOP;END$$;
DO $$DECLARE ds text[];BEGIN SELECT array_agg(d ORDER BY n) INTO ds FROM(SELECT d,min(n)n FROM unnest(erp_access_private.domains()||ARRAY['cheques'])WITH ORDINALITY x(d,n)GROUP BY d)y;EXECUTE format('CREATE OR REPLACE FUNCTION erp_access_private.domains() RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path='''' AS $f$SELECT %L::text[]$f$',ds);UPDATE public.erp_roles SET permissions=jsonb_build_object('cheques',jsonb_build_object('read',false,'create',false,'update',false,'delete',false,'approve',false,'settings',false,'files',false))||permissions;END$$;
CREATE FUNCTION erp_cheque_private.allowed(c uuid,a text) RETURNS boolean LANGUAGE sql STABLE SET search_path='' AS $$SELECT coalesce(brand_finance_private.role_for(c) IN('owner','manager','accountant','auditor') AND(a='read' OR brand_finance_private.role_for(c)<>'auditor') AND(a<>'settings' OR brand_finance_private.role_for(c)='owner') AND erp_access_private.allowed(c,'cheques',a),false)$$;
CREATE FUNCTION erp_cheque_private.authorize(c uuid,a text DEFAULT 'read') RETURNS void LANGUAGE plpgsql SET search_path='' AS $$BEGIN IF NOT erp_cheque_private.allowed(c,a) THEN RAISE EXCEPTION 'لا تملك صلاحية الشيكات المطلوبة' USING ERRCODE='42501';END IF;END$$;
CREATE FUNCTION erp_cheque_private.period(c uuid,d date) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$BEGIN PERFORM brand_finance_private.seed(c);IF d IS NULL OR NOT isfinite(d) OR d>(now() AT TIME ZONE 'Asia/Riyadh')::date OR EXISTS(SELECT 1 FROM public.bf_settings WHERE cafe_id=c AND closed_through>=d) THEN RAISE EXCEPTION 'تاريخ العملية غير صالح أو الفترة مغلقة';END IF;END$$;
CREATE FUNCTION erp_cheque_private.account(c uuid,i uuid,kinds text[]) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$BEGIN IF NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=c AND id=i AND kind=ANY(kinds) AND active AND NOT coalesce(is_group,false) AND NOT coalesce(frozen,false) AND deleted_at IS NULL AND NOT coalesce(is_cashier_drawer,false)) THEN RAISE EXCEPTION 'اختر حسابًا نشطًا من النوع المطلوب';END IF;END$$;
CREATE FUNCTION erp_cheque_private.control_account(c uuid,code text,label text,kind text) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$DECLARE i uuid;BEGIN SELECT id INTO i FROM public.bf_accounts WHERE cafe_id=c AND bf_accounts.code=control_account.code;IF i IS NULL THEN INSERT INTO public.bf_accounts(cafe_id,code,name,kind,active)VALUES(c,code,label,kind,true)RETURNING id INTO i;END IF;PERFORM erp_cheque_private.account(c,i,ARRAY[kind]);RETURN i;END$$;
CREATE FUNCTION erp_cheque_private.settings(c uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$SELECT jsonb_build_object('revision',coalesce(s.revision,0),'receivableAccountId',NULL,'payableAccountId',NULL,'depositAccountId',NULL,'feeAccountId',NULL,'allowEarlyCollection',false)||coalesce(s.payload,'{}')||jsonb_build_object('revision',coalesce(s.revision,0))FROM(SELECT 1)x LEFT JOIN public.erp_cheque_settings s ON s.cafe_id=c$$;
CREATE FUNCTION erp_cheque_private.config_account(c uuid,key text) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$DECLARE cfg jsonb:=erp_cheque_private.settings(c);i uuid:=(cfg->>key)::uuid;kind text;BEGIN
 kind:=CASE key WHEN 'payableAccountId' THEN 'payable' WHEN 'feeAccountId' THEN 'expense' ELSE 'receivable' END;
 IF i IS NULL THEN i:=erp_cheque_private.control_account(c,CASE key WHEN 'payableAccountId' THEN '2025' WHEN 'feeAccountId' THEN '5305' WHEN 'depositAccountId' THEN '1321' ELSE '1320' END,CASE key WHEN 'payableAccountId' THEN 'أوراق الدفع' WHEN 'feeAccountId' THEN 'رسوم تحصيل الشيكات' WHEN 'depositAccountId' THEN 'شيكات تحت التحصيل' ELSE 'أوراق القبض' END,kind);ELSE PERFORM erp_cheque_private.account(c,i,ARRAY[kind]);END IF;RETURN i;END$$;
CREATE FUNCTION erp_cheque_private.document(c uuid,i uuid,d date,note text) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$DECLARE doc uuid:=gen_random_uuid();q public.erp_cheques;BEGIN SELECT * INTO STRICT q FROM public.erp_cheques WHERE cafe_id=c AND id=i;PERFORM erp_cheque_private.period(c,d);INSERT INTO public.bf_documents(id,cafe_id,kind,total,paid,note,party_id,created_by,created_at)VALUES(doc,c,'journal',q.base_amount,0,left('شيك '||q.number||' '||coalesce(note,''),1000),q.party_id,auth.uid(),(d+time '12:00') AT TIME ZONE 'Asia/Riyadh');RETURN doc;END$$;
CREATE FUNCTION erp_cheque_private.reversal(c uuid,i uuid,d date,note text) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$DECLARE e public.erp_cheque_events;doc uuid;l public.bf_journal;BEGIN
 SELECT * INTO e FROM public.erp_cheque_events WHERE cafe_id=c AND id=i;IF e.id IS NULL OR e.document_id IS NULL OR EXISTS(SELECT 1 FROM public.erp_cheque_events WHERE cafe_id=c AND reversal_of=i) OR d<e.effective_on THEN RAISE EXCEPTION 'القيد غير متاح للتراجع بهذا التاريخ';END IF;
 doc:=erp_cheque_private.document(c,e.cheque_id,d,note);FOR l IN SELECT * FROM public.bf_journal WHERE cafe_id=c AND document_id=e.document_id LOOP PERFORM brand_finance_private.line(c,doc,l.account_id,l.credit,l.debit,l.party_id);END LOOP;RETURN doc;
END$$;
CREATE FUNCTION erp_cheque_private.save_book(c uuid,p jsonb) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$DECLARE old public.erp_cheque_books;i uuid:=(p->>'id')::uuid;f bigint;l bigint;BEGIN
 IF EXISTS(SELECT 1 FROM public.erp_cheque_books WHERE id=i AND cafe_id<>c)THEN RAISE EXCEPTION 'الدفتر غير متاح' USING ERRCODE='42501';END IF;
 SELECT * INTO old FROM public.erp_cheque_books WHERE cafe_id=c AND id=i FOR UPDATE;PERFORM erp_cheque_private.authorize(c,CASE WHEN old.id IS NULL THEN 'create' ELSE 'update' END);
 IF coalesce(old.revision,0) IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'دفتر الشيكات تغير' USING ERRCODE='40001';END IF;
 IF i IS NULL OR jsonb_typeof(p->'firstSerial') IS DISTINCT FROM 'number' OR jsonb_typeof(p->'lastSerial') IS DISTINCT FROM 'number' OR jsonb_typeof(p->'active') IS DISTINCT FROM 'boolean' OR coalesce(p->>'currency','')!~'^[A-Z]{3}$' OR length(btrim(coalesce(p->>'number',''))) NOT BETWEEN 1 AND 100 OR length(coalesce(p->>'note',''))>5000 THEN RAISE EXCEPTION 'راجع بيانات دفتر الشيكات';END IF;
 IF trunc((p->>'firstSerial')::numeric)<>(p->>'firstSerial')::numeric OR trunc((p->>'lastSerial')::numeric)<>(p->>'lastSerial')::numeric THEN RAISE EXCEPTION 'أرقام الشيكات يجب أن تكون صحيحة';END IF;f:=(p->>'firstSerial')::bigint;l:=(p->>'lastSerial')::bigint;IF f<1 OR l<f OR l>999999999999 OR l-f>1000000 THEN RAISE EXCEPTION 'نطاق أرقام الشيكات غير صالح';END IF;PERFORM erp_cheque_private.account(c,(p->>'bankId')::uuid,ARRAY['bank']);
 IF EXISTS(SELECT 1 FROM public.erp_cheque_books WHERE cafe_id=c AND id<>i AND bank_id=(p->>'bankId')::uuid AND first_serial<=l AND last_serial>=f) THEN RAISE EXCEPTION 'نطاق الأرقام يتداخل مع دفتر آخر';END IF;
 IF EXISTS(SELECT 1 FROM public.erp_cheques WHERE cafe_id=c AND book_id=i) AND(old.bank_id IS DISTINCT FROM(p->>'bankId')::uuid OR old.currency IS DISTINCT FROM p->>'currency' OR EXISTS(SELECT 1 FROM public.erp_cheques WHERE cafe_id=c AND book_id=i AND number::bigint NOT BETWEEN f AND l)) THEN RAISE EXCEPTION 'لا يمكن تغيير البنك أو العملة أو استبعاد أرقام مستخدمة';END IF;
 INSERT INTO public.erp_cheque_books(cafe_id,id,bank_id,number,first_serial,last_serial,currency,active,note)VALUES(c,i,(p->>'bankId')::uuid,btrim(p->>'number'),f,l,p->>'currency',(p->>'active')::boolean,coalesce(p->>'note',''))ON CONFLICT(id)DO UPDATE SET revision=erp_cheque_books.revision+1,bank_id=excluded.bank_id,number=excluded.number,first_serial=excluded.first_serial,last_serial=excluded.last_serial,currency=excluded.currency,active=excluded.active,note=excluded.note;RETURN i;
END$$;
CREATE FUNCTION erp_cheque_private.save(c uuid,p jsonb) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$DECLARE old public.erp_cheques;b public.erp_cheque_books;i uuid:=(p->>'id')::uuid;amount numeric;rate numeric;d date;due date;counter uuid:=(p->>'counterAccountId')::uuid;party uuid:=(p->>'partyId')::uuid;BEGIN
 IF EXISTS(SELECT 1 FROM public.erp_cheques WHERE id=i AND cafe_id<>c)THEN RAISE EXCEPTION 'الشيك غير متاح' USING ERRCODE='42501';END IF;
 SELECT * INTO old FROM public.erp_cheques WHERE cafe_id=c AND id=i FOR UPDATE;PERFORM erp_cheque_private.authorize(c,CASE WHEN old.id IS NULL THEN 'create' ELSE 'update' END);IF coalesce(old.revision,0) IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'الشيك تغير أعد تحميله' USING ERRCODE='40001';END IF;
 IF i IS NULL OR coalesce(p->>'kind','') NOT IN('payable','receivable') OR jsonb_typeof(p->'amount') IS DISTINCT FROM 'number' OR jsonb_typeof(p->'exchangeRate') IS DISTINCT FROM 'number' OR coalesce(p->>'currency','')!~'^[A-Z]{3}$' OR length(btrim(coalesce(p->>'number',''))) NOT BETWEEN 1 AND 100 OR length(btrim(coalesce(p->>'name',''))) NOT BETWEEN 1 AND 200 OR length(coalesce(p->>'note',''))>5000 OR length(coalesce(p->>'issuerBank',''))>200 OR length(coalesce(p->>'endorsementName',''))>200 OR jsonb_typeof(p->'endorsed') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع بيانات الشيك';END IF;
 amount:=(p->>'amount')::numeric;rate:=(p->>'exchangeRate')::numeric;d:=(p->>'issuedOn')::date;due:=(p->>'dueOn')::date;IF amount<=0 OR amount>1e9 OR amount<>round(amount,2) OR rate<=0 OR rate>1e6 OR round(amount*rate,2)>1e9 OR round(amount*rate,2)<=0 OR(p->>'currency'='SAR' AND rate<>1) OR d IS NULL OR NOT isfinite(d) OR due IS NOT NULL AND NOT isfinite(due) OR d>(now() AT TIME ZONE 'Asia/Riyadh')::date OR due<d THEN RAISE EXCEPTION 'راجع قيمة الشيك والعملات والتواريخ';END IF;
 IF(p->>'endorsed')::boolean AND length(btrim(coalesce(p->>'endorsementName','')))=0 THEN RAISE EXCEPTION 'أدخل اسم المظهر إليه';END IF;
 IF old.id IS NOT NULL AND old.kind IS DISTINCT FROM p->>'kind' THEN RAISE EXCEPTION 'لا يمكن تغيير نوع الشيك';END IF;
 IF old.id IS NOT NULL AND(old.status<>'issued' OR EXISTS(SELECT 1 FROM public.erp_cheque_events WHERE cafe_id=c AND cheque_id=i AND document_id IS NOT NULL)) THEN
  IF (old.payload-ARRAY['revision','name','dueOn','note','endorsed','endorsementName']) IS DISTINCT FROM(p-ARRAY['revision','name','dueOn','note','endorsed','endorsementName']) THEN RAISE EXCEPTION 'القيم المالية مثبتة بعد التسجيل وتعدل بالتراجع ثم إنشاء شيك بديل';END IF;
 ELSE
  PERFORM erp_cheque_private.account(c,(p->>'bankId')::uuid,ARRAY['bank']);PERFORM erp_cheque_private.account(c,counter,CASE p->>'kind' WHEN 'payable' THEN ARRAY['payable','expense','equity','receivable'] ELSE ARRAY['receivable','revenue','equity','payable'] END);
  IF EXISTS(SELECT 1 FROM public.bf_accounts WHERE id=counter AND kind IN('payable','receivable')) AND party IS NULL THEN RAISE EXCEPTION 'حدد العميل أو المورد المرتبط بحساب الذمم';END IF;
  IF party IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=c AND id=party AND active) THEN RAISE EXCEPTION 'الطرف غير متاح';END IF;
  IF p->>'kind'='payable' THEN SELECT * INTO b FROM public.erp_cheque_books WHERE cafe_id=c AND id=(p->>'bookId')::uuid FOR UPDATE;IF b.id IS NULL OR NOT b.active OR b.bank_id IS DISTINCT FROM(p->>'bankId')::uuid OR b.currency<>p->>'currency' OR(p->>'number')!~'^[0-9]{1,12}$' THEN RAISE EXCEPTION 'حدد دفترًا نشطًا ورقم شيك صالحًا';END IF;IF(p->>'number')::bigint NOT BETWEEN b.first_serial AND b.last_serial OR(p->>'number')<>((p->>'number')::bigint)::text THEN RAISE EXCEPTION 'رقم الشيك خارج الدفتر';END IF;
  ELSIF nullif(p->>'bookId','') IS NOT NULL THEN RAISE EXCEPTION 'الشيك المستلم لا يرتبط بدفتر صادر';END IF;
 END IF;
 INSERT INTO public.erp_cheques(cafe_id,id,kind,status,number,book_id,bank_id,counter_account_id,party_id,amount,base_amount,currency,exchange_rate,issued_on,due_on,name,payload,created_by)VALUES(c,i,p->>'kind','issued',btrim(p->>'number'),(p->>'bookId')::uuid,(p->>'bankId')::uuid,counter,party,amount,round(amount*rate,2),p->>'currency',rate,d,due,btrim(p->>'name'),p-'revision',auth.uid())ON CONFLICT(id)DO UPDATE SET revision=erp_cheques.revision+1,number=excluded.number,book_id=excluded.book_id,bank_id=excluded.bank_id,counter_account_id=excluded.counter_account_id,party_id=excluded.party_id,amount=excluded.amount,base_amount=excluded.base_amount,currency=excluded.currency,exchange_rate=excluded.exchange_rate,issued_on=excluded.issued_on,due_on=excluded.due_on,name=excluded.name,payload=excluded.payload;
 INSERT INTO public.erp_cheque_events(cafe_id,cheque_id,action,from_status,to_status,effective_on,payload,actor)VALUES(c,i,CASE WHEN old.id IS NULL THEN 'create' ELSE 'edit' END,old.status,coalesce(old.status,'issued'),d,jsonb_build_object('name',p->>'name','dueOn',due),auth.uid());RETURN i;
END$$;
CREATE FUNCTION erp_cheque_private.act(c uuid,a text,p jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $$DECLARE q public.erp_cheques;e public.erp_cheque_events;last_event public.erp_cheque_events;i uuid:=(p->>'id')::uuid;d date:=(p->>'date')::date;doc uuid;eid uuid;next text;holding uuid;deposit uuid;fee_account uuid;fee numeric:=coalesce((p->>'fee')::numeric,0);cfg jsonb:=erp_cheque_private.settings(c);BEGIN
 PERFORM erp_cheque_private.authorize(c,'approve');SELECT * INTO q FROM public.erp_cheques WHERE cafe_id=c AND id=i FOR UPDATE;IF q.id IS NULL THEN RAISE EXCEPTION 'الشيك غير متاح' USING ERRCODE='42501';END IF;IF q.revision IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'حالة الشيك تغيرت' USING ERRCODE='40001';END IF;
 PERFORM erp_cheque_private.period(c,d);IF d<q.issued_on OR d<coalesce((SELECT max(effective_on)FROM public.erp_cheque_events WHERE cafe_id=c AND cheque_id=i),q.issued_on) OR length(coalesce(p->>'note',''))>5000 THEN RAISE EXCEPTION 'تاريخ العملية يسبق حركة سابقة';END IF;
 IF a IN('deliver','receive') THEN
  IF q.status<>'issued' OR(a='deliver')<>(q.kind='payable') THEN RAISE EXCEPTION 'هذه الحالة لا تسمح بالتسليم أو الاستلام';END IF;
  PERFORM erp_cheque_private.account(c,q.counter_account_id,CASE q.kind WHEN 'payable' THEN ARRAY['payable','expense','equity','receivable'] ELSE ARRAY['receivable','revenue','equity','payable'] END);
  holding:=erp_cheque_private.config_account(c,CASE q.kind WHEN 'payable' THEN 'payableAccountId' ELSE 'receivableAccountId' END);IF holding=q.counter_account_id THEN RAISE EXCEPTION 'حساب الطرف يختلف عن حساب أوراق الشيكات';END IF;
  doc:=erp_cheque_private.document(c,i,d,p->>'note');IF q.kind='payable' THEN PERFORM brand_finance_private.line(c,doc,q.counter_account_id,q.base_amount,0,q.party_id);PERFORM brand_finance_private.line(c,doc,holding,0,q.base_amount,q.party_id);next:='delivered';ELSE PERFORM brand_finance_private.line(c,doc,holding,q.base_amount,0,q.party_id);PERFORM brand_finance_private.line(c,doc,q.counter_account_id,0,q.base_amount,q.party_id);next:='received';END IF;
  UPDATE public.erp_cheques SET holding_account_id=holding WHERE id=i;
 ELSIF a='deposit' THEN
  IF q.kind<>'receivable' OR q.status<>'received' THEN RAISE EXCEPTION 'يمكن إيداع الشيك المستلم فقط';END IF;
  deposit:=coalesce((p->>'depositAccountId')::uuid,erp_cheque_private.config_account(c,'depositAccountId'));PERFORM erp_cheque_private.account(c,deposit,ARRAY['receivable']);IF deposit IN(q.holding_account_id,q.counter_account_id) THEN RAISE EXCEPTION 'اختر حسابًا مستقلًا للشيكات تحت التحصيل';END IF;
  PERFORM erp_cheque_private.account(c,q.bank_id,ARRAY['bank']);doc:=erp_cheque_private.document(c,i,d,p->>'note');PERFORM brand_finance_private.line(c,doc,deposit,q.base_amount,0,q.party_id);PERFORM brand_finance_private.line(c,doc,q.holding_account_id,0,q.base_amount,q.party_id);next:='deposited';UPDATE public.erp_cheques SET deposit_account_id=deposit WHERE id=i;
 ELSIF a='collect' THEN
  IF q.status NOT IN('delivered','received','deposited') THEN RAISE EXCEPTION 'الشيك غير متاح للتحصيل';END IF;
  IF q.due_on>d AND NOT(cfg->>'allowEarlyCollection')::boolean THEN RAISE EXCEPTION 'لم يصل تاريخ استحقاق الشيك';END IF;
  IF jsonb_typeof(p->'fee') IS DISTINCT FROM 'number' OR fee<0 OR fee<>round(fee,2) OR fee>=q.base_amount OR q.kind='payable' AND fee<>0 THEN RAISE EXCEPTION 'راجع رسوم التحصيل بالريال';END IF;
  PERFORM erp_cheque_private.account(c,q.bank_id,ARRAY['bank']);IF q.kind='payable' AND coalesce((SELECT sum(debit-credit)FROM public.bf_journal WHERE cafe_id=c AND account_id=q.bank_id),0)<q.base_amount THEN RAISE EXCEPTION 'رصيد البنك لا يكفي لصرف الشيك';END IF;
  doc:=erp_cheque_private.document(c,i,d,p->>'note');holding:=CASE q.status WHEN 'deposited' THEN q.deposit_account_id ELSE q.holding_account_id END;
  IF q.kind='payable' THEN PERFORM brand_finance_private.line(c,doc,holding,q.base_amount,0,q.party_id);PERFORM brand_finance_private.line(c,doc,q.bank_id,0,q.base_amount);
  ELSE PERFORM brand_finance_private.line(c,doc,q.bank_id,q.base_amount-fee,0);PERFORM brand_finance_private.line(c,doc,holding,0,q.base_amount,q.party_id);IF fee>0 THEN fee_account:=coalesce((p->>'feeAccountId')::uuid,erp_cheque_private.config_account(c,'feeAccountId'));PERFORM erp_cheque_private.account(c,fee_account,ARRAY['expense']);PERFORM brand_finance_private.line(c,doc,fee_account,fee,0);END IF;END IF;next:='collected';
 ELSIF a IN('undo_collect','undo_deposit','undo_deliver') THEN
  IF(a='undo_collect' AND q.status<>'collected')OR(a='undo_deposit' AND q.status<>'deposited')OR(a='undo_deliver' AND q.status<>'delivered')THEN RAISE EXCEPTION 'لا تتوفر هذه العملية في حالة الشيك الحالية';END IF;
  SELECT * INTO e FROM public.erp_cheque_events x WHERE x.cafe_id=c AND x.cheque_id=i AND x.action=CASE a WHEN 'undo_collect' THEN 'collect' WHEN 'undo_deposit' THEN 'deposit' ELSE 'deliver' END AND NOT EXISTS(SELECT 1 FROM public.erp_cheque_events r WHERE r.cafe_id=c AND r.reversal_of=x.id)ORDER BY x.created_at DESC LIMIT 1;
  IF a='undo_collect' AND q.kind='receivable' AND coalesce((SELECT sum(debit-credit)FROM public.bf_journal WHERE cafe_id=c AND account_id=q.bank_id),0)<q.base_amount-coalesce((e.payload->>'fee')::numeric,0) THEN RAISE EXCEPTION 'رصيد البنك لا يكفي للتراجع عن التحصيل';END IF;
  doc:=erp_cheque_private.reversal(c,e.id,d,p->>'note');next:=e.from_status;INSERT INTO public.erp_cheque_events(cafe_id,cheque_id,action,from_status,to_status,effective_on,document_id,reversal_of,payload,actor)VALUES(c,i,a,q.status,next,d,doc,e.id,p-'revision',auth.uid())RETURNING id INTO eid;
 ELSIF a IN('reject','cancel') THEN
  IF q.status IN('collected','rejected','cancelled') OR(a='cancel' AND q.status<>'issued') THEN RAISE EXCEPTION 'تراجع عن التحصيل أو التسليم قبل الإلغاء';END IF;
  next:=CASE a WHEN 'reject' THEN 'rejected' ELSE 'cancelled' END;
  FOR e IN SELECT * FROM public.erp_cheque_events x WHERE x.cafe_id=c AND x.cheque_id=i AND x.action IN('receive','deliver','deposit') AND NOT EXISTS(SELECT 1 FROM public.erp_cheque_events r WHERE r.cafe_id=c AND r.reversal_of=x.id)ORDER BY x.created_at DESC LOOP doc:=erp_cheque_private.reversal(c,e.id,d,p->>'note');INSERT INTO public.erp_cheque_events(cafe_id,cheque_id,action,from_status,to_status,effective_on,document_id,reversal_of,payload,actor)VALUES(c,i,a,q.status,next,d,doc,e.id,p-'revision',auth.uid())RETURNING id INTO eid;END LOOP;
 ELSE RAISE EXCEPTION 'إجراء الشيك غير معروف';END IF;
 IF eid IS NULL THEN INSERT INTO public.erp_cheque_events(cafe_id,cheque_id,action,from_status,to_status,effective_on,document_id,payload,actor)VALUES(c,i,a,q.status,next,d,doc,p-'revision',auth.uid())RETURNING id INTO eid;END IF;
 UPDATE public.erp_cheques SET status=next,revision=revision+1 WHERE id=i;
 IF doc IS NOT NULL AND EXISTS(SELECT 1 FROM public.bf_journal WHERE document_id=doc HAVING abs(sum(debit-credit))>.001) THEN RAISE EXCEPTION 'قيد الشيك غير متوازن';END IF;RETURN jsonb_build_object('id',i,'eventId',eid,'documentId',doc,'status',next);
END$$;
CREATE FUNCTION public.erp_cheques_write(p_cafe_id uuid,p_action text,p_payload jsonb,p_request_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE c uuid:=p_cafe_id;p jsonb:=p_payload;r erp_cheque_private.requests;i uuid;result jsonb;q public.erp_cheques;cfg jsonb;k text;BEGIN
 PERFORM erp_cheque_private.authorize(c,'read');IF p_request_id IS NULL OR jsonb_typeof(p) IS DISTINCT FROM 'object' OR octet_length(p::text)>262144 THEN RAISE EXCEPTION 'بيانات العملية غير صالحة';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(c::text,60412));SELECT * INTO r FROM erp_cheque_private.requests WHERE cafe_id=c AND request_id=p_request_id;IF r.request_id IS NOT NULL THEN IF r.actor<>auth.uid() OR r.action<>p_action OR r.payload<>p THEN RAISE EXCEPTION 'معرف العملية مستخدم ببيانات مختلفة';END IF;RETURN r.result;END IF;
 IF p_action='book' THEN i:=erp_cheque_private.save_book(c,p);
 ELSIF p_action='delete_book' THEN PERFORM erp_cheque_private.authorize(c,'delete');IF NOT EXISTS(SELECT 1 FROM public.erp_cheque_books WHERE cafe_id=c AND id=(p->>'id')::uuid AND revision=(p->>'revision')::integer) THEN RAISE EXCEPTION 'دفتر الشيكات تغير' USING ERRCODE='40001';END IF;IF EXISTS(SELECT 1 FROM public.erp_cheques WHERE cafe_id=c AND book_id=(p->>'id')::uuid) THEN RAISE EXCEPTION 'الدفتر يحتوي شيكات ويمكن إيقافه بدل حذفه';END IF;DELETE FROM public.erp_cheque_books WHERE cafe_id=c AND id=(p->>'id')::uuid;i:=(p->>'id')::uuid;
 ELSIF p_action IN('save','save_receive','save_deliver') THEN i:=erp_cheque_private.save(c,p);IF p_action<>'save' THEN result:=erp_cheque_private.act(c,CASE p_action WHEN 'save_receive' THEN 'receive' ELSE 'deliver' END,jsonb_build_object('id',i,'revision',(SELECT revision FROM public.erp_cheques WHERE id=i),'date',p->>'issuedOn','note',p->>'note'));END IF;
 ELSIF p_action='delete' THEN PERFORM erp_cheque_private.authorize(c,'delete');SELECT * INTO q FROM public.erp_cheques WHERE cafe_id=c AND id=(p->>'id')::uuid;IF q.id IS NULL OR q.revision IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'الشيك تغير' USING ERRCODE='40001';END IF;IF q.status<>'issued' OR EXISTS(SELECT 1 FROM public.erp_cheque_events WHERE cafe_id=c AND cheque_id=q.id AND document_id IS NOT NULL) THEN RAISE EXCEPTION 'احفظ الشيك المسجل في السجل واستخدم الإلغاء أو الرفض';END IF;DELETE FROM public.erp_cheque_events WHERE cafe_id=c AND cheque_id=q.id;DELETE FROM public.erp_cheques WHERE cafe_id=c AND id=q.id;i:=q.id;
 ELSIF p_action='settings' THEN
  PERFORM erp_cheque_private.authorize(c,'settings');cfg:=erp_cheque_private.settings(c);IF(cfg->>'revision')::integer IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'الإعدادات تغيرت' USING ERRCODE='40001';END IF;
  IF jsonb_typeof(p->'allowEarlyCollection') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'حدد سياسة تاريخ التحصيل';END IF;
  FOREACH k IN ARRAY ARRAY['receivableAccountId','payableAccountId','depositAccountId','feeAccountId']LOOP IF NOT(p?k) OR jsonb_typeof(p->k) NOT IN('string','null')THEN RAISE EXCEPTION 'راجع حسابات دورة الشيكات';END IF;IF jsonb_typeof(p->k)='string' THEN PERFORM erp_cheque_private.account(c,(p->>k)::uuid,ARRAY[CASE k WHEN 'payableAccountId' THEN 'payable' WHEN 'feeAccountId' THEN 'expense' ELSE 'receivable' END]);END IF;END LOOP;
  IF p->>'receivableAccountId'=p->>'depositAccountId' AND p->>'receivableAccountId' IS NOT NULL THEN RAISE EXCEPTION 'افصل حساب أوراق القبض عن الشيكات تحت التحصيل';END IF;
  INSERT INTO public.erp_cheque_settings(cafe_id,payload)VALUES(c,p-'revision')ON CONFLICT(cafe_id)DO UPDATE SET revision=erp_cheque_settings.revision+1,payload=excluded.payload;
 ELSE result:=erp_cheque_private.act(c,p_action,p);i:=(result->>'id')::uuid;END IF;
 result:=coalesce(result,jsonb_build_object('id',i));INSERT INTO public.erp_cheque_audit(cafe_id,record_id,action,actor) VALUES(c,i,p_action,auth.uid());INSERT INTO erp_cheque_private.requests VALUES(c,p_request_id,auth.uid(),p_action,p,result);RETURN result;
END$$;
CREATE FUNCTION public.erp_cheques_read(p_cafe_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE c uuid:=p_cafe_id;BEGIN PERFORM erp_cheque_private.authorize(c,'read');RETURN jsonb_build_object(
 'settings',erp_cheque_private.settings(c),'canCreate',erp_cheque_private.allowed(c,'create'),'canUpdate',erp_cheque_private.allowed(c,'update'),'canDelete',erp_cheque_private.allowed(c,'delete'),'canApprove',erp_cheque_private.allowed(c,'approve'),'canConfigure',erp_cheque_private.allowed(c,'settings'),'canFiles',erp_cheque_private.allowed(c,'files'),
 'books',coalesce((SELECT jsonb_agg(jsonb_build_object('id',b.id,'revision',b.revision,'bankId',b.bank_id,'number',b.number,'firstSerial',b.first_serial,'lastSerial',b.last_serial,'currency',b.currency,'active',b.active,'note',b.note,'used',(SELECT count(*)FROM public.erp_cheques q WHERE q.cafe_id=c AND q.book_id=b.id),'nextSerial',(SELECT min(candidate)FROM(SELECT b.first_serial candidate UNION SELECT q.number::bigint+1 FROM public.erp_cheques q WHERE q.cafe_id=c AND q.book_id=b.id)t WHERE candidate<=b.last_serial AND NOT EXISTS(SELECT 1 FROM public.erp_cheques x WHERE x.cafe_id=c AND x.bank_id=b.bank_id AND x.kind='payable' AND x.number=candidate::text)))ORDER BY b.created_at DESC)FROM public.erp_cheque_books b WHERE b.cafe_id=c),'[]'),
 'cheques',coalesce((SELECT jsonb_agg(q.payload||jsonb_build_object('id',q.id,'revision',q.revision,'status',q.status,'baseAmount',q.base_amount,'holdingAccountId',q.holding_account_id,'depositAccountId',q.deposit_account_id,'createdAt',q.created_at)ORDER BY q.issued_on DESC,q.created_at DESC)FROM public.erp_cheques q WHERE q.cafe_id=c),'[]'),
 'events',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.id,'chequeId',e.cheque_id,'action',e.action,'fromStatus',e.from_status,'toStatus',e.to_status,'date',e.effective_on,'documentId',e.document_id,'reversalOf',e.reversal_of,'payload',e.payload,'createdAt',e.created_at)ORDER BY e.created_at DESC)FROM public.erp_cheque_events e WHERE e.cafe_id=c),'[]'),
 'accounts',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'kind',kind,'active',active AND NOT coalesce(frozen,false) AND NOT coalesce(is_group,false) AND deleted_at IS NULL AND NOT coalesce(is_cashier_drawer,false))ORDER BY code)FROM public.bf_accounts WHERE cafe_id=c),'[]'),
 'parties',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'kind',kind,'active',active)ORDER BY name)FROM public.bf_parties WHERE cafe_id=c),'[]'));END$$;
CREATE FUNCTION public.erp_cheques_report(p_cafe_id uuid,p_from date,p_to date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE c uuid:=p_cafe_id;BEGIN PERFORM erp_cheque_private.authorize(c,'read');IF p_from IS NULL OR p_to IS NULL OR p_from>p_to THEN RAISE EXCEPTION 'حدد فترة التقرير';END IF;RETURN jsonb_build_object('classification','cheque_register','currency','SAR','rows',coalesce((SELECT jsonb_agg(jsonb_build_object('id',q.id,'kind',q.kind,'date',q.issued_on,'number',q.number,'name',q.name,'account',a.name,'due',q.due_on,'amount',q.base_amount,'currency',q.currency,'originalAmount',q.amount,'status',q.status,'year',extract(year from q.issued_on),'matured',q.due_on<=(now()AT TIME ZONE'Asia/Riyadh')::date AND q.status IN('issued','received','delivered','deposited'),'cashMovement',coalesce((SELECT sum(j.debit-j.credit)FROM public.erp_cheque_events e JOIN public.bf_journal j ON j.cafe_id=e.cafe_id AND j.document_id=e.document_id JOIN public.bf_accounts ca ON ca.id=j.account_id WHERE e.cafe_id=c AND e.cheque_id=q.id AND e.effective_on BETWEEN p_from AND p_to AND ca.kind IN('cash','bank')),0)))FROM public.erp_cheques q JOIN public.bf_accounts a ON a.cafe_id=c AND a.id=q.bank_id WHERE q.cafe_id=c AND q.issued_on BETWEEN p_from AND p_to),'[]'));END$$;
ALTER FUNCTION erp_file_private.assert_record(uuid,text,uuid,boolean) RENAME TO assert_record_before_cheques;
CREATE FUNCTION erp_file_private.assert_record(c uuid,t text,i uuid,w boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN IF t='cheque' THEN PERFORM erp_cheque_private.authorize(c,CASE WHEN w THEN 'files' ELSE 'read' END);IF NOT EXISTS(SELECT 1 FROM public.erp_cheques WHERE cafe_id=c AND id=i)THEN RAISE EXCEPTION 'الشيك غير متاح' USING ERRCODE='42501';END IF;ELSE PERFORM erp_file_private.assert_record_before_cheques(c,t,i,w);END IF;END$$;
ALTER FUNCTION erp_access_private.file_domain(text)RENAME TO file_domain_before_cheques;
CREATE FUNCTION erp_access_private.file_domain(t text)RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$SELECT CASE WHEN t='cheque' THEN 'cheques' ELSE erp_access_private.file_domain_before_cheques(t)END$$;
CREATE TRIGGER erp_cheques_files_guard BEFORE DELETE ON public.erp_cheques FOR EACH ROW EXECUTE FUNCTION erp_file_private.prevent_orphans('cheque');
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA erp_cheque_private FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION erp_file_private.assert_record(uuid,text,uuid,boolean),erp_file_private.assert_record_before_cheques(uuid,text,uuid,boolean),erp_access_private.file_domain(text),erp_access_private.file_domain_before_cheques(text) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.erp_cheques_read(uuid),public.erp_cheques_write(uuid,text,jsonb,uuid),public.erp_cheques_report(uuid,date,date) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.erp_cheques_read(uuid),public.erp_cheques_write(uuid,text,jsonb,uuid),public.erp_cheques_report(uuid,date,date)TO authenticated;
NOTIFY pgrst,'reload schema';
COMMIT;
